/**
 * @distilled.cloud/temporal-cloud — Temporal Cloud Ops API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * in `.generated-specs` (written by `scripts/convert.ts` from the OpenAPI
 * spec). Everything else in this folder is hand-written.
 *
 * Most mutating Cloud Ops calls are asynchronous: they answer with an
 * `asyncOperation` whose `state` moves to `fulfilled` or `failed` later.
 * Poll `getAsyncOperation` with its `id` to wait for the change to land.
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/unstable/http/FetchHttpClient";
 * import * as TemporalCloud from "@distilled.cloud/temporal-cloud";
 *
 * const program = TemporalCloud.getNamespace({ namespace: "orders.a1b2c" });
 *
 * program.pipe(
 *   Effect.provide(
 *     Layer.mergeAll(
 *       FetchHttpClient.layer,
 *       TemporalCloud.CredentialsFromEnv,
 *       TemporalCloud.TemporalCloudProtocol,
 *     ),
 *   ),
 *   Effect.runPromise,
 * );
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  TemporalCloudProtocol,
  type TemporalCloudOpError,
  type TemporalCloudOpContext,
} from "./protocol.ts";
export { paginateCursor } from "./pagination.ts";
export * as Retry from "./retry.ts";
// Operations (and their request/response types) are importable straight off
// the package root. The service-local typed error classes shadow the
// same-named shared ones from ./errors.ts — the ops raise the service-local
// classes.
export * from "./services/temporal-cloud.ts";
